// @@shiny-variants-data-end

class ShinyVariants {
    // Same tints as PokéRogue: standard (gold), rare (cyan), epic (red)
    static VERSION = '1.3.4';
    static VARIANT_NAMES = ['Standard', 'Rare', 'Epic'];
    static VARIANT_COLORS = ['#f8c020', '#20f8f0', '#e81048'];
    static SETTING_KEYS = {
        recolor: 'shinyVariantsRecolor',
        stars: 'shinyVariantsStars',
        enemies: 'shinyVariantsEnemies',
    };

    static settings = {};
    // Decoded palettes, blob URLs of the recoloured sprites and the pending builds
    static palettes = new Map();
    static blobUrls = new Map();
    static builds = new Map();
    // One observable per sprite, bumped once its recoloured version exists so the
    // Knockout bindings that asked for it re-evaluate
    static versions = new Map();
    // Cleared when the canvas cannot read the sprites (tainted canvas): the
    // standard shiny sprites are shown for the rest of the session
    static recolorAvailable = true;
    // What the settings tab says about the recolouring, updated by the builds
    static recolorStatus = null;
    // Copy of the per-Pokémon data outside the game save, see storeMirror
    static mirror = null;
    // The enemy being caught, set around Battle.catchPokemon
    static catchContext = null;
    // Computed counts of Pokémon with a palette unlocked, for the achievements
    static counts = new Map();

    static windowObject() {
        return !App.isUsingClient ? unsafeWindow : window;
    }

    // ---------------------------------------------------------------------------------
    // Settings
    // ---------------------------------------------------------------------------------

    static loadSettings() {
        this.recolorStatus = ko.observable('no sprite requested yet');
        Object.entries(this.SETTING_KEYS).forEach(([name, key]) => {
            const stored = localStorage.getItem(key);
            const observable = ko.observable(stored === null ? true : stored === 'true');
            observable.subscribe((value) => localStorage.setItem(key, value));
            this.settings[name] = observable;
        });
    }

    // Runs once the game has loaded: the patches are already in place, only the
    // settings rows are left to build
    static initSettings() {
        if (!this.settings.recolor) {
            throw new Error('The Shiny Variants patches were not installed; the script probably loaded after the game started.');
        }
        const settingsBody = createScriptSettingsContainer('Shiny Variants');
        const rows = [
            ['recolor', 'Recolour shiny sprites with the palette shown'],
            ['stars', 'Show the palette stars in the Pokédex and the party list'],
            ['enemies', 'Wild shiny Pokémon show the palette they will unlock'],
        ];
        rows.forEach(([name, label]) => {
            const row = document.createElement('tr');
            row.innerHTML = `<td class="p-2" colspan="2"><label class="m-0" for="checkbox-shinyVariants-${name}">${label}</label>`
                + `<input id="checkbox-shinyVariants-${name}" type="checkbox" class="mx-2"></td>`;
            settingsBody.appendChild(row);
            const checkbox = row.querySelector('input');
            checkbox.checked = this.settings[name]();
            checkbox.addEventListener('change', (event) => {
                this.settings[name](event.target.checked);
            });
        });
        // What the save holds, refreshed each time the settings window opens
        const diagnostics = document.createElement('tr');
        diagnostics.innerHTML = '<td class="p-2 text-muted small" colspan="2"></td>';
        settingsBody.appendChild(diagnostics);
        const refreshDiagnostics = () => {
            diagnostics.firstChild.textContent = `Shiny Variants ${this.VERSION}. ${this.diagnostics()}`;
        };
        refreshDiagnostics();
        $('#settingsModal').on('shown.bs.modal', refreshDiagnostics);

        const coverage = document.createElement('tr');
        coverage.innerHTML = `<td class="p-2 text-muted small" colspan="2">Palettes from ${SHINY_VARIANT_DATA.src}, `
            + `${Object.keys(SHINY_VARIANT_DATA.p).filter((id) => !id.endsWith('-f')).length} Pokémon covered. `
            + 'A Pokémon without a palette still unlocks its variants, only its sprite stays the standard shiny one.<br>'
            + 'Sprite recolouring: <span></span></td>';
        settingsBody.appendChild(coverage);
        const status = coverage.querySelector('span');
        status.textContent = this.recolorStatus();
        this.recolorStatus.subscribe((text) => {
            status.textContent = text;
        });
    }

    // One line on the party's palettes, for the settings tab
    static diagnostics() {
        const party = App.game?.party?.caughtPokemon ?? [];
        const shinies = party.filter((pokemon) => pokemon.shiny);
        const counts = [1, 2].map((variant) => {
            const owners = shinies.filter((pokemon) => this.unlockedMask(pokemon) & (1 << variant));
            const drawable = owners.filter((pokemon) => this.hasPalette(pokemon.id, variant)).length;
            return `${owners.length} with ${this.VARIANT_NAMES[variant]} (${drawable} with a palette for it)`;
        });
        const picked = shinies.filter((pokemon) => this.stateOf(pokemon).shown() > 0).length;
        return `${shinies.length} shiny Pokémon: ${counts.join(', ')}, ${picked} with a palette picked by hand.`;
    }

    // ---------------------------------------------------------------------------------
    // Palettes and sprites
    // ---------------------------------------------------------------------------------

    static rollVariant() {
        // PokéRogue: 6 in 10 standard, 3 in 10 rare, 1 in 10 epic
        const roll = Rand.floor(10);
        return roll >= 4 ? 0 : (roll >= 1 ? 1 : 2);
    }

    static palette(dataKey, variant) {
        const cacheKey = `${dataKey}:${variant}`;
        if (!this.palettes.has(cacheKey)) {
            const encoded = SHINY_VARIANT_DATA.p[dataKey]?.[variant - 1];
            let table = null;
            if (encoded) {
                table = new Map();
                for (let i = 0; i + 12 <= encoded.length; i += 12) {
                    table.set(parseInt(encoded.slice(i, i + 6), 16), parseInt(encoded.slice(i + 6, i + 12), 16));
                }
            }
            this.palettes.set(cacheKey, table);
        }
        return this.palettes.get(cacheKey);
    }

    static paletteFor(pokemonId, female, variant) {
        if (!variant) {
            return null;
        }
        // A female entry, even an empty one, overrides the male palette for the female sprite
        if (female && SHINY_VARIANT_DATA.p[`${pokemonId}-f`]) {
            return this.palette(`${pokemonId}-f`, variant);
        }
        return this.palette(String(pokemonId), variant);
    }

    static hasPalette(pokemonId, variant) {
        return !!this.paletteFor(pokemonId, false, variant);
    }

    static versionFor(key) {
        if (!this.versions.has(key)) {
            this.versions.set(key, ko.observable(0));
        }
        return this.versions.get(key);
    }

    // The recoloured sprite for a shiny sprite path, or that path while the
    // recoloured one is being built (the caller is re-evaluated once it is)
    static imageFor(pokemonId, variant, shinySrc) {
        // Shadow shinies have their own artwork, the palettes do not apply to them
        if (!variant || !this.recolorAvailable || !this.settings.recolor() || !shinySrc.startsWith('assets/images/shinypokemon/')) {
            return shinySrc;
        }
        const female = shinySrc.endsWith('-f.png');
        const palette = this.paletteFor(pokemonId, female, variant);
        if (!palette) {
            return shinySrc;
        }
        const key = `${pokemonId}${female ? '-f' : ''}:${variant}`;
        const cached = this.blobUrls.get(key);
        if (cached) {
            return cached;
        }
        this.versionFor(key)();
        this.ensureBuild(key, shinySrc.replace('assets/images/shinypokemon/', 'assets/images/pokemon/'), palette);
        return shinySrc;
    }

    // Same as imageFor, but waits for the recoloured sprite
    static async variantImage(pokemonId, variant, shinySrc) {
        const src = this.imageFor(pokemonId, variant, shinySrc);
        const key = `${pokemonId}${shinySrc.endsWith('-f.png') ? '-f' : ''}:${variant}`;
        return (await this.builds.get(key)) ?? src;
    }

    static ensureBuild(key, basePath, palette) {
        if (!this.builds.has(key)) {
            this.builds.set(key, this.buildVariantImage(key, basePath, palette).catch((error) => {
                console.warn(`Shiny Variants: could not build the sprite ${key}`, error);
                if (!this.blobUrls.size) {
                    this.recolorStatus(`failed on ${key}: ${error.message}`);
                }
                return null;
            }));
        }
        return this.builds.get(key);
    }

    // The sprite as something a canvas can draw and read back: fetched as a blob
    // and turned into a bitmap, its pixels stay readable whatever origin the page
    // runs from (the desktop client runs it from file://)
    static async loadSprite(basePath) {
        if (typeof createImageBitmap === 'function') {
            const response = await fetch(basePath);
            if (!response.ok) {
                throw new Error(`${response.status} ${response.statusText} loading ${basePath}`);
            }
            return createImageBitmap(await response.blob());
        }
        const image = new Image();
        image.src = basePath;
        await image.decode();
        return image;
    }

    static async buildVariantImage(key, basePath, palette) {
        const sprite = await this.loadSprite(basePath);
        const canvas = document.createElement('canvas');
        canvas.width = sprite.naturalWidth ?? sprite.width;
        canvas.height = sprite.naturalHeight ?? sprite.height;
        const context = canvas.getContext('2d');
        context.drawImage(sprite, 0, 0);
        let imageData;
        try {
            imageData = context.getImageData(0, 0, canvas.width, canvas.height);
        } catch (error) {
            // Tainted canvas: the sprites are not readable from this origin
            if (this.recolorAvailable) {
                console.warn('Shiny Variants: the sprites cannot be recoloured in this browser, showing the standard shiny sprites', error);
            }
            this.recolorAvailable = false;
            this.recolorStatus(`unavailable: ${error.message}`);
            return null;
        }
        this.recolorPixels(imageData.data, palette, SHINY_VARIANT_DATA.tol);
        context.putImageData(imageData, 0, 0);
        const blob = await new Promise((resolve) => canvas.toBlob(resolve, 'image/png'));
        const url = URL.createObjectURL(blob);
        this.blobUrls.set(key, url);
        this.recolorStatus(`working (${this.blobUrls.size} sprite${this.blobUrls.size > 1 ? 's' : ''} recoloured this session)`);
        const version = this.versionFor(key);
        version(version() + 1);
        return url;
    }

    // Replaces in place every opaque pixel whose colour is in the palette, or
    // within the tolerance of one of its colours, by the palette's replacement.
    // Pure: tools/shinyvariants/test-recolor.mjs runs this very code.
    // @@recolor-begin
    static recolorPixels(data, palette, tolerance) {
        const resolved = new Map();
        const lookup = (color) => {
            if (resolved.has(color)) {
                return resolved.get(color);
            }
            let target = palette.get(color);
            if (target === undefined) {
                target = null;
                let best = Infinity;
                const r = color >> 16;
                const g = (color >> 8) & 0xff;
                const b = color & 0xff;
                palette.forEach((replacement, source) => {
                    const dr = Math.abs((source >> 16) - r);
                    const dg = Math.abs(((source >> 8) & 0xff) - g);
                    const db = Math.abs((source & 0xff) - b);
                    if (dr <= tolerance && dg <= tolerance && db <= tolerance && dr + dg + db < best) {
                        best = dr + dg + db;
                        target = replacement;
                    }
                });
            }
            resolved.set(color, target);
            return target;
        };
        for (let i = 0; i < data.length; i += 4) {
            if (data[i + 3] === 0) {
                continue;
            }
            const target = lookup((data[i] << 16) | (data[i + 1] << 8) | data[i + 2]);
            if (target !== null) {
                data[i] = target >> 16;
                data[i + 1] = (target >> 8) & 0xff;
                data[i + 2] = target & 0xff;
            }
        }
    }
    // @@recolor-end

    // ---------------------------------------------------------------------------------
    // Per-Pokémon state
    // ---------------------------------------------------------------------------------

    // mask: bit v set when palette v is unlocked; shown: 0 when the highest unlocked
    // palette is displayed, palette + 1 once one was picked in the statistics window.
    // A shiny with an empty mask is one caught before this script: standard palette.
    static stateOf(pokemon) {
        if (!pokemon.shinyVariantState) {
            pokemon.shinyVariantState = { mask: ko.observable(0), shown: ko.observable(0) };
        }
        return pokemon.shinyVariantState;
    }

    static unlockedMask(pokemon) {
        return this.stateOf(pokemon).mask() || (pokemon.shiny ? 1 : 0);
    }

    static unlockedCount(pokemonId) {
        const pokemon = App.game?.party.getPokemon(pokemonId);
        if (!pokemon?.shiny) {
            return 0;
        }
        const mask = this.unlockedMask(pokemon);
        return [0, 1, 2].filter((variant) => mask & (1 << variant)).length;
    }

    // The palette to draw for a party Pokémon: the one chosen in its statistics
    // window (shown = palette + 1) while it is unlocked, otherwise the highest
    // unlocked one, which is what PokéRogue shows by default
    static shownVariant(pokemonId) {
        const pokemon = App.game?.party.getPokemon(pokemonId);
        if (!pokemon?.shiny) {
            return 0;
        }
        const mask = this.unlockedMask(pokemon);
        const chosen = this.stateOf(pokemon).shown() - 1;
        if (chosen >= 0 && (mask & (1 << chosen))) {
            return chosen;
        }
        return [2, 1, 0].find((variant) => mask & (1 << variant)) ?? 0;
    }

    static cycle(pokemonId) {
        const pokemon = App.game.party.getPokemon(pokemonId);
        if (!pokemon?.shiny) {
            return;
        }
        const mask = this.unlockedMask(pokemon);
        const current = this.shownVariant(pokemonId);
        for (let step = 1; step <= 3; step++) {
            const next = (current + step) % 3;
            if (mask & (1 << next)) {
                this.stateOf(pokemon).shown(next + 1);
                return;
            }
        }
    }

    // The variant a caught shiny brings: the one its wild form was showing when it
    // comes from a battle or the Safari, a fresh roll otherwise (eggs, gifts, codes)
    static caughtVariantFor(pokemonId) {
        const candidates = [this.catchContext, typeof SafariBattle !== 'undefined' ? SafariBattle.enemy : null];
        const enemy = candidates.find((candidate) => candidate?.shiny && candidate.id === pokemonId);
        return enemy ? enemy.shinyVariant : this.rollVariant();
    }

    static unlock(pokemon, variant, hadShiny) {
        const state = this.stateOf(pokemon);
        const before = hadShiny ? this.unlockedMask(pokemon) : 0;
        const bit = 1 << variant;
        state.mask(before | bit);
        if (!hadShiny) {
            // No choice made yet: the highest unlocked palette shows
            state.shown(0);
        }
        // The game already announces the first shiny; the other unlocks are ours
        if (!(before & bit) && (hadShiny || variant > 0)) {
            this.notifyUnlock(pokemon, variant);
        }
    }

    static async notifyUnlock(pokemon, variant) {
        const shinySrc = this.windowObject().PokemonHelper.getImage(pokemon.id, true, undefined, undefined, 0);
        const pokemonImage = await this.variantImage(pokemon.id, variant, shinySrc);
        Notifier.notify({
            message: `✨ ${pokemon.displayName} unlocked its ${this.VARIANT_NAMES[variant].toLowerCase()} shiny palette! ✨`,
            pokemonImage,
            type: NotificationConstants.NotificationOption.warning,
            sound: NotificationConstants.NotificationSound.General.new_catch,
            setting: NotificationConstants.NotificationSetting.General.new_catch,
        });
    }

    // ---------------------------------------------------------------------------------
    // Achievements, through the Custom Achievements script when it is installed
    // ---------------------------------------------------------------------------------

    // Party Pokémon with the palette unlocked, one computed per palette and region so
    // the achievements share the work; region null counts every Pokémon
    static countUnlocked(variant, region = null) {
        const key = `${variant}:${region ?? 'all'}`;
        if (!this.counts.has(key)) {
            this.counts.set(key, ko.pureComputed(() => {
                const bit = 1 << variant;
                const owners = App.game.party.caughtPokemon.filter((pokemon) => pokemon.id > 0
                    && (this.unlockedMask(pokemon) & bit)
                    && (region === null || PokemonHelper.calcNativeRegion(pokemon.name) === region));
                // Regions count species, like the game's own Shiny Trainer achievements
                return region === null ? owners.length : new Set(owners.map((pokemon) => Math.floor(pokemon.id))).size;
            }));
        }
        return this.counts.get(key)();
    }

    // Mirrors the game's shiny achievements for each of the two extra palettes
    static achievementDefinitions() {
        const tiers = [
            [1, 0.03], [10, 0.06], [20, 0.09], [30, 0.12], [40, 0.15], [50, 0.30],
            [75, 0.45], [100, 0.60], [151, 1.00], [250, 1.20], [500, 1.30], [1000, 1.50],
        ];
        const names = {
            1: [
                'A Different Kind of Shiny', 'Blue Is the New Gold', 'Cool Colours Club', 'Not Just a Trick of the Light',
                'Second Wardrobe Collector', 'Sapphire Sparkles', 'The Odds Just Got Longer', 'One Hundred Shades Rarer',
                'One Hundred Fifty-One Ways to Say Rare', 'Cyan Cyclone', 'Rarer Than Rare', 'Rare Is the New Normal',
            ],
            2: [
                'Painting the Town Red', 'Ten Times the Legend', 'Crimson Collection', 'Epic Is an Understatement',
                'Forty Shades of Wow', 'Red Carpet Roster', 'Seventy-Five Jackpots', 'A Hundred Miracles',
                'One Hundred Fifty-One Legends', 'Ruby Rush', 'Statistically Impossible', 'Epic Is the New Normal',
            ],
        };
        const category = { name: 'shinyVariants', displayName: 'Shiny Variants', bonus: 100 };
        const type = GameConstants.AchievementType['Shiny Pokemon'];
        const definitions = [];
        [1, 2].forEach((variant) => {
            const label = this.VARIANT_NAMES[variant];
            tiers.forEach(([amount, bonus], index) => {
                definitions.push({
                    name: names[variant][index],
                    description: `Capture ${amount.toLocaleString('en-US')} unique ${label} Shiny Pokémon.`,
                    progress: () => this.countUnlocked(variant),
                    amount,
                    bonus,
                    category,
                    type,
                    series: `shinyVariant:${variant}`,
                    hint: `${amount.toLocaleString('en-US')} ${label} Shiny Pokémon need to be obtained.`,
                });
            });
            GameHelper.enumNumbers(GameConstants.Region).filter((region) => region >= GameConstants.Region.kanto && region < GameConstants.Region.final).forEach((region) => {
                const regionName = GameConstants.camelCaseToString(GameConstants.Region[region]);
                const unique = PokemonHelper.calcUniquePokemonsByRegion(region);
                [['Trainer', Math.floor(unique * 0.1), 3], ['Ace', Math.floor(unique * 0.5), 6], ['Master', Math.floor(unique), 9]].forEach(([rank, amount, bonus]) => {
                    definitions.push({
                        name: `${regionName} ${label} Shiny ${rank}`,
                        description: rank === 'Master'
                            ? `Complete the ${regionName} ${label} Shiny Pokédex!`
                            : `Catch ${amount} unique ${label} Shiny Pokémon native to the ${regionName} region.`,
                        progress: () => this.countUnlocked(variant, region),
                        amount,
                        bonus,
                        category,
                        type,
                        series: `shinyVariant:${variant}:${region}`,
                        hint: `${amount} unique ${label} Shiny Pokémon native to ${regionName} need to be caught.`,
                        achievable: () => player.highestRegion() >= region,
                    });
                });
            });
        });
        return definitions;
    }

    // ---------------------------------------------------------------------------------
    // Persistence
    // ---------------------------------------------------------------------------------

    // The unmodified game drops the two extra keys from a Pokémon on its next save,
    // so the same data is mirrored per save file in the browser storage and used
    // when the save no longer has it: a session without the script loses nothing.
    static mirrorKey() {
        return `shinyVariants-${Save.key}`;
    }

    static MIRROR_VERSION = 3;

    static loadMirror() {
        if (this.mirror?.saveKey === Save.key) {
            return this.mirror;
        }
        let entries = {};
        let version = this.MIRROR_VERSION;
        try {
            const stored = JSON.parse(localStorage.getItem(this.mirrorKey()));
            if (stored?.v >= 2) {
                entries = stored.e ?? {};
                version = stored.v;
            } else if (stored) {
                // Version 1 mirrors stored the displayed palette itself
                Object.entries(stored).forEach(([id, [mask, shown]]) => {
                    entries[id] = [mask, shown ? shown + 1 : 0];
                });
                version = 1;
            }
        } catch {
            entries = {};
        }
        this.mirror = { saveKey: Save.key, entries, version, serialized: null };
        return this.mirror;
    }

    static mirrorEntry(pokemonId) {
        return this.loadMirror().entries[pokemonId];
    }

    // Version 1.3.1 turned the svd: 0 of the first saves into a Standard palette
    // picked by hand (svp: 1) and saved it that way; a save last written by it
    // (mirror version 2) gets those picks dropped, the highest palette shows again
    static repairPick(shown) {
        return this.loadMirror().version < 3 && shown === 1 ? 0 : shown;
    }

    static saveEntry(pokemon) {
        const state = pokemon.shinyVariantState;
        if (!state) {
            return null;
        }
        const mask = state.mask();
        const shown = state.shown();
        const implied = pokemon.shiny ? 1 : 0;
        if ((mask === 0 || mask === implied) && shown === 0) {
            return null;
        }
        return [mask, shown];
    }

    static storeMirror(party) {
        const entries = {};
        party.caughtPokemon.forEach((pokemon) => {
            const entry = this.saveEntry(pokemon);
            if (entry) {
                entries[pokemon.id] = entry;
            }
        });
        const serialized = JSON.stringify({ v: this.MIRROR_VERSION, e: entries });
        if (this.mirror?.saveKey === Save.key && this.mirror.serialized === serialized) {
            return;
        }
        localStorage.setItem(this.mirrorKey(), serialized);
        this.mirror = { saveKey: Save.key, entries, version: this.MIRROR_VERSION, serialized };
    }

    // ---------------------------------------------------------------------------------
    // Stars
    // ---------------------------------------------------------------------------------

    static showStars(pokemonId) {
        return this.settings.stars() && !!App.game?.party.getPokemon(pokemonId)?.shiny;
    }

    static starSvg(symbol, color, title) {
        return `<svg class="sv-star sv-${symbol}" style="color: ${color};" viewBox="0 0 ${this.iconSize(symbol)}">`
            + `<title>${title}</title><use href="#sv-icon-${symbol}"></use></svg>`;
    }

    static iconSize(symbol) {
        const icon = symbol === 'small' ? SHINY_VARIANT_DATA.icons.small : SHINY_VARIANT_DATA.icons.page[Number(symbol.slice(-1))];
        return `${icon.w} ${icon.h}`;
    }

    // Lists: PokéRogue's grid stacks one small star per unlocked palette, tinted
    // with that palette, the lower palettes to the right
    static starsHtml(pokemonId) {
        const pokemon = App.game?.party.getPokemon(pokemonId);
        if (!pokemon?.shiny) {
            return '';
        }
        const mask = this.unlockedMask(pokemon);
        return [0, 1, 2]
            .filter((variant) => mask & (1 << variant))
            .map((variant) => this.starSvg('small', this.VARIANT_COLORS[variant], `${this.VARIANT_NAMES[variant]} shiny palette`))
            .join('');
    }

    // Detail window: PokéRogue's Pokédex page shows the three palette icons,
    // black while locked, grey once unlocked, tinted for the one displayed
    static pageStarsHtml(pokemonId) {
        const pokemon = App.game?.party.getPokemon(pokemonId);
        if (!pokemon?.shiny) {
            return '';
        }
        const mask = this.unlockedMask(pokemon);
        const shown = this.shownVariant(pokemonId);
        return [0, 1, 2].map((variant) => {
            const unlocked = mask & (1 << variant);
            const color = !unlocked ? '#000000' : (variant === shown ? this.VARIANT_COLORS[variant] : '#808080');
            const title = `${this.VARIANT_NAMES[variant]} shiny palette${unlocked ? '' : ' (not unlocked)'}`;
            return this.starSvg(`page-${variant}`, color, title);
        }).join('');
    }

    static variantLabel(pokemonId) {
        const shown = this.shownVariant(pokemonId);
        return this.VARIANT_NAMES[shown] + (shown > 0 && !this.hasPalette(pokemonId, shown) ? ' (no sprite)' : '');
    }

    static variantHint(pokemonId) {
        if (this.unlockedCount(pokemonId) > 1) {
            return 'Show the next unlocked palette';
        }
        return 'Catch or hatch this shiny again to unlock another palette';
    }

    // ---------------------------------------------------------------------------------
    // Game patches, run on document ready before the game starts
    // ---------------------------------------------------------------------------------

    static installGamePatches() {
        const windowObject = this.windowObject();
        if (windowObject.PokemonHelper?.shinyVariantsPatched) {
            console.warn('Shiny Variants: patches already installed, skipping');
            return;
        }
        if (typeof App !== 'undefined' && App.game) {
            throw new Error('The game started before the Shiny Variants script loaded; the variants cannot be added this session.');
        }
        this.loadSettings();

        // PokemonHelper is a module namespace whose members cannot be reassigned,
        // but the global itself can: the templates and the game scripts resolve it
        // on the window at call time. getImage gains a fifth argument, the palette
        // to draw; without it the party Pokémon's chosen palette is used.
        const original = windowObject.PokemonHelper;
        const wrapper = Object.create(original);
        // A plain assignment would hit the inherited getter-only member and throw
        Object.defineProperty(wrapper, 'getImage', {
            configurable: true,
            enumerable: true,
            writable: true,
            value: function (pokemonId, shiny, gender, shadow, variant) {
                const src = original.getImage.call(this, pokemonId, shiny, gender, shadow);
                if (!src.startsWith('assets/images/shinypokemon/')) {
                    return src;
                }
                return ShinyVariants.imageFor(pokemonId, variant ?? ShinyVariants.shownVariant(pokemonId), src);
            },
        });
        wrapper.shinyVariantsPatched = true;
        windowObject.PokemonHelper = wrapper;

        // Wild and Safari Pokémon roll their palette when first drawn, and the
        // modules' own getImage (an internal import, not the global) is wrapped so
        // the battle sprite shows it
        [BattlePokemon, SafariPokemon].forEach((klass) => {
            Object.defineProperty(klass.prototype, 'shinyVariant', {
                configurable: true,
                get() {
                    if (this._shinyVariant === undefined) {
                        this._shinyVariant = this.shiny ? ShinyVariants.rollVariant() : 0;
                    }
                    return this._shinyVariant;
                },
            });
            const getImageOld = klass.prototype.getImage;
            klass.prototype.getImage = function (...args) {
                // Custom artwork (this.image) and non-shinies are the game's business
                if (this.image || !this.shiny) {
                    return getImageOld.apply(this, args);
                }
                const variant = ShinyVariants.settings.enemies() ? this.shinyVariant : 0;
                return ShinyVariants.windowObject().PokemonHelper.getImage(this.id, this.shiny, this.gender, this.shadow, variant);
            };
        });

        // Battle.catchPokemon receives the enemy being caught (routes and dungeons):
        // remember it so the party gets the palette that enemy was showing
        const catchPokemonOld = Battle.catchPokemon;
        Battle.catchPokemon = function (enemyPokemon, ...args) {
            ShinyVariants.catchContext = enemyPokemon;
            try {
                return catchPokemonOld.call(this, enemyPokemon, ...args);
            } finally {
                ShinyVariants.catchContext = null;
            }
        };

        // Every way of obtaining a Pokémon ends in gainPokemonById, where the game
        // turns the shiny flag on once and for all; the palettes unlock one by one
        const gainPokemonByIdOld = Party.prototype.gainPokemonById;
        Party.prototype.gainPokemonById = function (id, shiny = false, ...args) {
            if (!shiny) {
                return gainPokemonByIdOld.call(this, id, shiny, ...args);
            }
            const hadShiny = this.alreadyCaughtPokemon(id, true);
            const variant = ShinyVariants.caughtVariantFor(id);
            const result = gainPokemonByIdOld.call(this, id, shiny, ...args);
            const pokemon = this.getPokemon(id);
            if (pokemon) {
                ShinyVariants.unlock(pokemon, variant, hadShiny);
            }
            return result;
        };

        // Two extra keys per Pokémon in the game save, unknown to the game's own
        // fromJSON (which ignores them) and added after its toJSON (which only
        // strips the keys it knows): sv the unlocked mask, svp the palette picked
        // (palette + 1; absent while the highest unlocked one shows). svd was the
        // picked palette itself in the first versions of the script.
        const toJSONOld = PartyPokemon.prototype.toJSON;
        PartyPokemon.prototype.toJSON = function (...args) {
            const output = toJSONOld.apply(this, args);
            const entry = ShinyVariants.saveEntry(this);
            if (entry) {
                output.sv = entry[0];
                if (entry[1]) {
                    output.svp = entry[1];
                }
            }
            return output;
        };
        const fromJSONOld = PartyPokemon.prototype.fromJSON;
        PartyPokemon.prototype.fromJSON = function (json, ...args) {
            const result = fromJSONOld.call(this, json, ...args);
            if (json?.id != null) {
                const mirrored = ShinyVariants.mirrorEntry(this.id);
                const state = ShinyVariants.stateOf(this);
                // The first versions wrote svd: 0 for every Pokémon with a palette; only
                // a non-zero value was a palette picked on purpose
                const legacyShown = json.svd ? Number(json.svd) + 1 : undefined;
                state.mask(Number(json.sv ?? mirrored?.[0] ?? 0) || 0);
                state.shown(ShinyVariants.repairPick(Number(json.svp ?? legacyShown ?? mirrored?.[1] ?? 0) || 0));
            }
            return result;
        };
        const partyToJSONOld = Party.prototype.toJSON;
        Party.prototype.toJSON = function (...args) {
            const output = partyToJSONOld.apply(this, args);
            ShinyVariants.storeMirror(this);
            return output;
        };

        this.injectStars();
        this.installFilters();

        // Achievements for the two extra palettes, picked up by the Custom Achievements
        // script when it is installed, whichever of the two scripts loads first
        windowObject.CustomAchievementsQueue = windowObject.CustomAchievementsQueue ?? [];
        windowObject.CustomAchievementsQueue.push(() => ShinyVariants.achievementDefinitions());
    }

    // Rare and Epic entries in the Pokédex "Caught Status" and the Hatchery "Shiny
    // Status" filters, next to the game's Shiny ones
    static installFilters() {
        // Pokédex: the game's list ignores a status it does not know, so the extra
        // statuses only narrow its result down to the Pokémon holding the palette
        const dexFilter = Settings.getSetting('pokedexCaughtFilter');
        const dexStatuses = { 'caught-shiny-rare': 1, 'caught-shiny-epic': 2 };
        dexFilter.options.push(new SettingOption('Caught Rare Shiny', 'caught-shiny-rare'), new SettingOption('Caught Epic Shiny', 'caught-shiny-epic'));
        const getListOld = PokedexHelper.getList;
        PokedexHelper.getList = function (...args) {
            const list = getListOld.apply(this, args);
            const variant = dexStatuses[dexFilter.observableValue()];
            if (!variant) {
                return list;
            }
            return list.filter((pokemon) => {
                const partyPokemon = App.game.party.getPokemon(pokemon.id);
                return !!partyPokemon?.shiny && (ShinyVariants.unlockedMask(partyPokemon) & (1 << variant));
            });
        };

        // Hatchery: the game compares the status to the shiny flag itself, so the
        // game reads Rare (2) and Epic (3) as Shiny (1) while the select keeps the
        // real value, and the list is narrowed down to the palette afterwards
        const hatcheryFilter = Settings.getSetting('breedingShinyFilter');
        hatcheryFilter.options.push(new SettingOption('Rare Shiny', 2), new SettingOption('Epic Shiny', 3));
        const rawValue = hatcheryFilter.observableValue;
        hatcheryFilter.rawObservableValue = rawValue;
        hatcheryFilter.observableValue = ko.pureComputed({
            read: () => Math.min(rawValue(), 1),
            write: (value) => rawValue(value),
        });
        const select = document.getElementById('breeding-filter-shiny-status');
        if (select) {
            select.setAttribute('data-bind', select.getAttribute('data-bind').replace('value: breedingShinyFilter.observableValue', 'value: breedingShinyFilter.rawObservableValue'));
        } else {
            console.warn('Shiny Variants: Hatchery shiny filter not found, its select will show Shiny for the new statuses');
        }
        const hatcheryListOld = BreedingController.hatcheryFilteredList;
        BreedingController.hatcheryFilteredList = ko.pureComputed(() => {
            const list = hatcheryListOld();
            const variant = rawValue() - 1;
            if (variant < 1) {
                return list;
            }
            return list.filter((pokemon) => ShinyVariants.unlockedMask(pokemon) & (1 << variant));
        });
    }

    // The stars go into the game's own templates before it applies its Knockout
    // bindings, so every rendered row gets its copy bound to that row's data
    static injectStars() {
        // PokéRogue's star pixel art as SVG symbols, tinted through currentColor
        const symbols = [['small', SHINY_VARIANT_DATA.icons.small], ...SHINY_VARIANT_DATA.icons.page.map((icon, variant) => [`page-${variant}`, icon])];
        const sheet = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
        sheet.setAttribute('style', 'position: absolute; width: 0; height: 0; overflow: hidden;');
        sheet.setAttribute('aria-hidden', 'true');
        sheet.innerHTML = symbols.map(([name, icon]) => `<symbol id="sv-icon-${name}" viewBox="0 0 ${icon.w} ${icon.h}">`
            + icon.paths.map(([opacity, d]) => `<path fill="currentColor" fill-opacity="${opacity}" shape-rendering="crispEdges" d="${d}"></path>`).join('')
            + '</symbol>').join('');
        document.body.prepend(sheet);

        const style = document.createElement('style');
        style.textContent = `
            .sv-stars { display: inline-flex; flex-direction: row-reverse; align-items: center; vertical-align: middle; line-height: 1; }
            .sv-stars .sv-star { display: block; width: 16px; height: 16px; }
            .sv-stars .sv-small + .sv-small { margin-right: -4px; }
            .sv-stars .sv-page-0, .sv-stars .sv-page-1, .sv-stars .sv-page-2 { width: 30px; height: 28px; margin-right: 2px; }
            .sv-stars.sv-page-row { flex-direction: row; }
            #pokedexModal .pokedexEntry .sv-stars { position: absolute; left: 3px; top: 26px; }
            #pokemonListContainer sup.sv-stars .sv-star { width: 12px; height: 12px; }
            #pokemonListContainer sup.sv-stars .sv-small + .sv-small { margin-right: -3px; }
        `;
        document.head.appendChild(style);

        // Pokédex tile: $data is the pokemonList entry
        const dexBadge = document.querySelector('#pokedexModal li.pokedexEntry div[data-bind="visible: App.game.party.alreadyCaughtPokemonByName(name)"]');
        if (dexBadge) {
            const stars = document.createElement('div');
            stars.className = 'sv-stars';
            stars.setAttribute('data-bind', 'visible: ShinyVariants.showStars($data.id), html: ShinyVariants.starsHtml($data.id)');
            dexBadge.after(stars);
        } else {
            console.warn('Shiny Variants: Pokédex tile not found, no stars there');
        }

        // Party list: $data is the PartyPokemon; the stars replace the game's ✨
        const partySparkle = document.querySelector('#pokemonListContainer sup[data-bind="visible: $data.shiny"]');
        if (partySparkle) {
            partySparkle.setAttribute('data-bind', 'visible: $data.shiny && !ShinyVariants.settings.stars()');
            const stars = document.createElement('sup');
            stars.className = 'sv-stars';
            stars.setAttribute('data-bind', 'visible: ShinyVariants.showStars($data.id), html: ShinyVariants.starsHtml($data.id)');
            partySparkle.after(stars);
        } else {
            console.warn('Shiny Variants: party list not found, no stars there');
        }

        // Statistics window: $data is the Pokémon id, and the row sits in the
        // game's own "if shiny" block next to the Hide Shiny Sprite toggle
        const hideShinyToggle = document.querySelector('#pokemonStatisticsModal input[data-bind="checked: App.game.party.getPokemon($data).hideShinyImage"]');
        if (hideShinyToggle) {
            const row = document.createElement('tr');
            row.innerHTML = '<td class="text-left align-middle text-nowrap">Shiny Palette</td>'
                + '<td class="text-left tight">'
                + '<span class="sv-stars sv-page-row" data-bind="html: ShinyVariants.pageStarsHtml($data)"></span>'
                + '<button class="btn btn-sm btn-primary py-0 ml-2" data-bind="click: () => ShinyVariants.cycle($data), '
                + 'text: ShinyVariants.variantLabel($data), enable: ShinyVariants.unlockedCount($data) > 1, '
                + 'attr: { title: ShinyVariants.variantHint($data) }">Standard</button>'
                + '</td>';
            hideShinyToggle.closest('tr').after(row);
        } else {
            console.warn('Shiny Variants: statistics window not found, no palette switch there');
        }
    }
}

/**
 * Creates container for scripts settings in the settings menu, adding scripts tab if it doesn't exist yet
 */
function createScriptSettingsContainer(name) {
    const settingsID = name.replaceAll(/s/g, '').toLowerCase();
    var settingsContainer = document.getElementById('settings-scripts-container');

    // Create scripts settings tab if it doesn't exist yet
    if (!settingsContainer) {
        // Fixes the Scripts nav item getting wrapped to the bottom by increasing the max width of the window
        document.querySelector('#settingsModal div').style.maxWidth = '850px';
        // Create and attach script settings tab link
        const settingTabs = document.querySelector('#settingsModal ul.nav-tabs');
        const li = document.createElement('li');
        li.classList.add('nav-item');
        li.innerHTML = `<a class="nav-link" href="#settings-scripts" data-toggle="tab">Scripts</a>`;
        settingTabs.appendChild(li);
        // Create and attach script settings tab contents
        const tabContent = document.querySelector('#settingsModal .tab-content');
        scriptSettings = document.createElement('div');
        scriptSettings.classList.add('tab-pane');
        scriptSettings.setAttribute('id', 'settings-scripts');
        tabContent.appendChild(scriptSettings);
        settingsContainer = document.createElement('div');
        settingsContainer.setAttribute('id', 'settings-scripts-container');
        scriptSettings.appendChild(settingsContainer);
    }

    // Create settings container
    const settingsTable = document.createElement('table');
    settingsTable.classList.add('table', 'table-striped', 'table-hover', 'm-0');
    const header = document.createElement('thead');
    header.innerHTML = `<tr><th colspan="2">${name}</th></tr>`;
    settingsTable.appendChild(header);
    const settingsBody = document.createElement('tbody');
    settingsBody.setAttribute('id', `settings-scripts-${settingsID}`);
    settingsTable.appendChild(settingsBody);

    // Insert settings container in alphabetical order
    let settingsList = Array.from(settingsContainer.children);
    let insertBefore = settingsList.find(elem => elem.querySelector('tbody').id > `settings-scripts-${settingsID}`);
    if (insertBefore) {
        insertBefore.before(settingsTable);
    } else {
        settingsContainer.appendChild(settingsTable);
    }

    return settingsBody;
}

function loadEpheniaScript(scriptName, initFunction, priorityFunction) {
    function reportScriptError(scriptName, error) {
        console.error(`Error while initializing '${scriptName}' userscript:\n${error}`);
        Notifier.notify({
            type: NotificationConstants.NotificationOption.warning,
            title: scriptName,
            message: `The '${scriptName}' userscript crashed while loading. Check for updates or disable the script, then restart the game.\n\nReport script issues to the script developer, not to the Pokéclicker team.`,
            timeout: GameConstants.DAY,
        });
    }
    const windowObject = !App.isUsingClient ? unsafeWindow : window;
    // Inject handlers if they don't exist yet
    if (windowObject.epheniaScriptInitializers === undefined) {
        windowObject.epheniaScriptInitializers = {};
        const oldInit = Preload.hideSplashScreen;
        var hasInitialized = false;

        // Initializes scripts once enough of the game has loaded
        Preload.hideSplashScreen = function (...args) {
            var result = oldInit.apply(this, args);
            if (App.game && !hasInitialized) {
                // Initialize all attached userscripts
                Object.entries(windowObject.epheniaScriptInitializers).forEach(([scriptName, initFunction]) => {
                    try {
                        initFunction();
                    } catch (e) {
                        reportScriptError(scriptName, e);
                    }
                });
                hasInitialized = true;
            }
            return result;
        }
    }

    // Prevent issues with duplicate script names
    if (windowObject.epheniaScriptInitializers[scriptName] !== undefined) {
        console.warn(`Duplicate '${scriptName}' userscripts found!`);
        Notifier.notify({
            type: NotificationConstants.NotificationOption.warning,
            title: scriptName,
            message: `Duplicate '${scriptName}' userscripts detected. This could cause unpredictable behavior and is not recommended.`,
            timeout: GameConstants.DAY,
        });
        let number = 2;
        while (windowObject.epheniaScriptInitializers[`${scriptName} ${number}`] !== undefined) {
            number++;
        }
        scriptName = `${scriptName} ${number}`;
    }
    // Add initializer for this particular script
    windowObject.epheniaScriptInitializers[scriptName] = initFunction;
    // Run any functions that need to execute before the game starts
    if (priorityFunction) {
        $(document).ready(() => {
            try {
                priorityFunction();
            } catch (e) {
                reportScriptError(scriptName, e);
                // Remove main initialization function
                windowObject.epheniaScriptInitializers[scriptName] = () => null;
            }
        });
    }
}

if (!App.isUsingClient || localStorage.getItem('shinyvariants') === 'true') {
    // The Knockout bindings injected in the templates resolve ShinyVariants on the page's window
    (!App.isUsingClient ? unsafeWindow : window).ShinyVariants = ShinyVariants;
    loadEpheniaScript('shinyvariants', () => ShinyVariants.initSettings(), () => ShinyVariants.installGamePatches());
}
